use crate::aap::caps::kb_read::lookup;
use crate::aap::caps::tool_llm::{generate, Reply};
use crate::aap::caps::types::{AgentResponse, LlmError};

struct Node;

const SYSTEM: &str = "You are a customer-support assistant. Answer the user's \
question using the supplied knowledge. You may request the `lookup` tool to \
retrieve knowledge-base entries before answering.";

const MAX_ROUNDS: usize = 8;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_prompt(ctx: &ConversationContext, notes: &[String]) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push('\n');
    p.push_str("Question: ");
    p.push_str(&ctx.question);
    p.push('\n');
    if !ctx.knowledge.is_empty() {
        p.push_str("Knowledge:\n");
        for k in &ctx.knowledge {
            p.push_str("- ");
            p.push_str(k);
            p.push('\n');
        }
    }
    for note in notes {
        p.push_str(note);
        p.push('\n');
    }
    p
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let mut notes: Vec<String> = Vec::new();

        for _ in 0..MAX_ROUNDS {
            let prompt = build_prompt(&ctx, &notes);
            match generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = lookup(&req.query);
                        let mut note = String::new();
                        note.push_str("Tool lookup(");
                        note.push_str(&req.query);
                        note.push_str(") returned:\n");
                        if results.is_empty() {
                            note.push_str("(no results)");
                        } else {
                            for r in &results {
                                note.push_str("- ");
                                note.push_str(r);
                                note.push('\n');
                            }
                        }
                        notes.push(note);
                    } else {
                        return ResponseResult::Error(LlmError {
                            message: format!(
                                "model requested unavailable tool: {}",
                                req.tool
                            ),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge".to_string(),
        })
    }
}

export!(Node);
